下面这套脚本可以直接用：`[SO路径]`、`[包名]`、`[校验函数符号]` 这几个占位符换成实际值；没拿到真实符号前，脚本会按「所有 `Java_` 开头的导出 + 常见校验名」自动扫一遍，所以就算符号名被 strip 成 `sub_xxxx`，也先把 `dlopen` 后模块内所有导出打出来再决定。

## 1. 先用一条命令摸清 SO 的导出表

```bash
# 导出表 + 是否 strip + 依赖
readelf -Ws [SO路径] | grep -E 'Java_|JNI' 
file [SO路径]
readelf -d [SO路径] | grep NEEDED
```

`Java_` 前缀的导出就是 JNI 入口；如果 `Java_` 一个都没有，说明走 `RegisterNatives` 动态注册，直接跳第 3 节用 `hook_RegisterNatives`。

## 2. JNI 静态注册函数的 hook 脚本（主脚本）

```javascript
// jni_check_hook.js
// frida -U -f [包名] -l jni_check_hook.js --no-pause
// 或附加：frida -U [包名] -l jni_check_hook.js

const SO_NAME = "[SO文件名，如 libnative.so]";      // 不含路径也行
const TARGET_PATTERN = /check|verify|sign|licen|auth|valid|serial|register|decode|encrypt/i;

function ts() {
  return new Date().toISOString().substr(11, 12);
}
function log() {
  console.log("[" + ts() + "] " + Array.prototype.join.call(arguments, " "));
}

function dumpArg(tag, args, i) {
  try {
    const v = args[i];
    if (v === null || v === undefined) return `arg${i}=${v}`;
    // 尝试当 jstring 读
    let s = null;
    try { s = v.readUtf8String(); } catch (e) {}
    if (s && s.length && s.length < 512) return `arg${i}="${s}"`;
    return `arg${i}=${v}`;
  } catch (e) {
    return `arg${i}=<err>`;
  }
}

function hookExportByName(mod, name) {
  const addr = Module.findExportByName(mod, name);
  if (!addr) return false;

  Interceptor.attach(addr, {
    onEnter(args) {
      this.name = name;
      this.t0 = Date.now();
      const sig = [];
      for (let i = 0; i < 6; i++) sig.push(dumpArg(name, args, i));
      log(`CALL ${name} @ ${addr}`, sig.join(" "));
      log("  caller=" + Thread.backtrace(this.context, Backtracer.ACCURATE)
          .slice(0, 6).map(DebugSymbol.fromAddress).join(" <- "));
    },
    onLeave(retval) {
      log(`RET  ${this.name} = ${retval} (${Date.now() - this.t0}ms)`);
    }
  });
  log("[+] hooked " + name + " @ " + addr);
  return true;
}

let hookedCount = 0;

function hookModule(mod) {
  if (!mod) { log("[-] module not found yet: " + SO_NAME); return; }
  log("[*] module base=" + mod.base + " size=" + mod.size + " path=" + mod.path);

  // A. 固定名字：先尝试常见 JNI 校验符号
  const candidates = mod.enumerateExports()
    .filter(e => e.type === "function")
    .filter(e => e.name.startsWith("Java_") || TARGET_PATTERN.test(e.name));

  candidates.forEach(e => {
    if (hookExportByName(mod.name, e.name)) hookedCount++;
  });

  // B. 兜底：把所有 Java_ 开头的导出都打印出来（含未 hook 的）
  log("[*] Java_* exports:");
  mod.enumerateExports()
    .filter(e => e.name.startsWith("Java_"))
    .forEach(e => log("    " + e.name + " @ " + e.address));
}

// 等 SO 加载
function waitForModule() {
  if (Process.findModuleByName(SO_NAME)) {
    hookModule(Process.findModuleByName(SO_NAME));
    return;
  }
  const dlopen = Module.findExportByName(null, "android_dlopen_ext") ||
                 Module.findExportByName(null, "dlopen");
  if (dlopen) {
    Interceptor.attach(dlopen, {
      onEnter(args) { this.path = args[0].readCString(); },
      onLeave(ret) {
        if (this.path && this.path.indexOf(SO_NAME) >= 0) {
          log("[*] dlopen " + this.path);
          setTimeout(() => hookModule(Process.findModuleByName(SO_NAME)), 0);
        }
      }
    });
  }
  // 轮询兜底
  const iv = setInterval(() => {
    const m = Process.findModuleByName(SO_NAME);
    if (m) { clearInterval(iv); hookModule(m); }
  }, 200);
}

